(function(global){"use strict";const DATA={"area":{"id":"elar-reading","shortTitle":"ELAR/Reading","eyebrow":"Texas ELAR and reading certification preparation","heroTitle":"Decode accurately. Read critically. Write with evidence.","heroText":"Diagnostics and targeted practice for EC–6 ELAR 901, Core Subjects 4–8 ELAR 806, standalone ELAR 4–8 (217), and Science of Teaching Reading (293).","about":"The ELAR/reading site covers language, foundational reading, text comprehension, writing, conventions, research and media literacy, assessment, differentiation, and evidence-based reading instruction. Constructed responses are practiced through self-assessed writing labs because they cannot be scored reliably by a static browser site.","links":[{"label":"Core Subjects EC–6 (391) framework — ELAR 901","url":"https://www.tx.nesinc.com/Content/StudyGuide/TX_SG_obj_391.htm"},{"label":"Core Subjects 4–8 (211) framework — ELAR 806","url":"https://www.tx.nesinc.com/Content/StudyGuide/TX_SG_obj_211_2021.htm"},{"label":"English Language Arts and Reading 4–8 (217) framework","url":"https://www.tx.nesinc.com/Content/StudyGuide/TX_SG_obj_217.htm"},{"label":"Science of Teaching Reading (293) framework","url":"https://www.tx.nesinc.com/Content/StudyGuide/TX_SG_obj_293.htm"}]},"categories":{"el-oral":{"label":"Oral Language and Language Structure","description":"Phonology, morphology, syntax, semantics, pragmatics, listening, speaking, register, and academic discussion.","group":"Language Foundations","questions":[{"prompt":"Which term refers to the sound system of a language?","correct":"Phonology","distractors":["Syntax","Semantics","Pragmatics"],"explanation":"Phonology concerns speech sounds and sound patterns; syntax concerns sentence structure, semantics meaning, and pragmatics language use in context."},{"prompt":"Which term refers to the rules for arranging words into sentences?","correct":"Syntax","distractors":["Phonology","Morphology only","Prosody"],"explanation":"Syntax governs sentence structure and word order."},{"prompt":"Which term refers to how context influences the meaning and appropriateness of language?","correct":"Pragmatics","distractors":["Orthography","Phonics","Syllabication"],"explanation":"Pragmatics includes conversational rules, implied meanings, audience, purpose, and social context."},{"prompt":"A student can explain an idea informally to a friend but struggles to present it to a class. Which language skill needs the most support?","correct":"Adapting register and organization for audience and purpose","distractors":["Recognizing individual phonemes only","Alphabet formation only","Silent reading rate only"],"explanation":"Effective speaking requires adjusting vocabulary, detail, tone, and structure for the audience and occasion."},{"prompt":"Which activity best develops active listening?","correct":"Students paraphrase a partner’s claim and ask a relevant follow-up question.","distractors":["Students wait silently without processing the message.","Students copy a written paragraph.","Students speak at the same time."],"explanation":"Paraphrasing and questioning demonstrate attention, comprehension, and purposeful response."},{"prompt":"A student says, “She go to the store yesterday.” Which aspect of language is most directly involved?","correct":"Grammar and morphology","distractors":["Phonemic segmentation only","Print directionality","Visual literacy only"],"explanation":"The sentence shows difficulties with tense marking and subject–verb form."},{"prompt":"Which classroom structure most supports equitable academic discussion?","correct":"Provide clear norms, think time, accountable talk stems, and multiple ways to participate.","distractors":["Call only on the fastest volunteers.","Grade students on how often they interrupt.","Avoid giving students time to prepare."],"explanation":"Structured participation supports listening, evidence use, and access for students with varied language strengths."},{"prompt":"Which response best demonstrates paraphrasing?","correct":"Restating the speaker’s main idea accurately in new words","distractors":["Repeating every word exactly","Changing the claim into an unrelated opinion","Giving a judgment without describing the message"],"explanation":"A paraphrase preserves meaning while using different wording."},{"prompt":"A student uses the phrase “Could you please clarify that point?” during a discussion. This phrase primarily serves which pragmatic function?","correct":"Requesting clarification politely","distractors":["Changing verb tense","Identifying a vowel team","Marking a paragraph boundary"],"explanation":"The phrase manages interaction by asking for more information in a socially appropriate way."},{"prompt":"Which factor most strongly affects whether spoken language is formal or informal?","correct":"Audience, purpose, and setting","distractors":["The number of syllables in every word","The speaker’s height","The page size of a transcript"],"explanation":"Register changes according to context and communicative purpose."},{"prompt":"Which activity best integrates oral and written language?","correct":"Students discuss evidence from a text, draft a claim, and revise it after peer questions.","distractors":["Students copy isolated spelling words only.","Students listen to music without responding.","Students complete an unrelated worksheet silently."],"explanation":"Discussion can rehearse ideas and language that students then develop in writing."},{"prompt":"What is prosody in oral reading or speech?","correct":"The rhythm, phrasing, stress, and intonation of language","distractors":["The dictionary definition of a word","The number of letters in a sentence","The arrangement of pages in a book"],"explanation":"Prosody conveys structure and meaning through expressive features of speech."},{"prompt":"Which question requires inferential listening?","correct":"What unstated concern can be inferred from the speaker’s examples and tone?","distractors":["What exact date did the speaker state?","How many times was a word repeated?","What was the first sentence?"],"explanation":"Inferential listening combines explicit details with context and tone to derive unstated meaning."},{"prompt":"A student alternates appropriately between two languages depending on audience and setting. This is best understood as:","correct":"strategic language variation rather than evidence of confusion.","distractors":["an inability to learn syntax.","a reading disability by itself.","a failure to understand meaning."],"explanation":"Multilingual speakers often use their linguistic repertoires flexibly and purposefully."},{"prompt":"Which oral presentation feature most helps listeners follow a complex explanation?","correct":"A clear organizational preview and verbal transitions","distractors":["Frequent unrelated details","Reading every slide without emphasis","Avoiding any signal of sequence"],"explanation":"Previewing structure and using transitions makes relationships among ideas explicit."}]},"el-phonological":{"label":"Phonological and Phonemic Awareness","description":"Words, syllables, onset-rime, rhyme, phoneme isolation, blending, segmentation, deletion, and substitution.","group":"Foundational Reading","questions":[{"prompt":"Which task measures phonemic awareness rather than phonics?","correct":"Say the sounds in “ship” without looking at print.","distractors":["Read the printed word “ship.”","Match the written letters sh to a sound.","Spell the word “ship.”"],"explanation":"Phonemic awareness is conscious manipulation of speech sounds without requiring print."},{"prompt":"How many phonemes are in the word “ship”?","correct":"3","distractors":["4","2","5"],"explanation":"The phonemes are /sh/ /i/ /p/; the digraph sh represents one sound."},{"prompt":"How many phonemes are in the word “box”?","correct":"4","distractors":["3","2","5"],"explanation":"The sounds are /b/ /o/ /k/ /s/; x commonly represents two phonemes /k/ and /s/."},{"prompt":"Which activity practices phoneme blending?","correct":"The teacher says /m/ /ă/ /p/, and the student says “map.”","distractors":["The student separates “map” into three sounds.","The student removes /m/ from “map.”","The student identifies the first letter in print."],"explanation":"Blending combines separate phonemes into a spoken word."},{"prompt":"Which activity practices phoneme segmentation?","correct":"The student says /f/ /ĭ/ /sh/ for “fish.”","distractors":["The student combines /f/ /ĭ/ /sh/.","The student reads a printed sentence.","The student copies the word “fish.”"],"explanation":"Segmentation breaks a spoken word into its component phonemes."},{"prompt":"Which activity practices phoneme deletion?","correct":"Say “smile” without /s/.","distractors":["Add /s/ to the beginning of “mile.”","Blend /s/ /m/ /ī/ /l/.","Identify the rhyme in “smile.”"],"explanation":"Deletion removes a specified phoneme; “smile” without /s/ is “mile.”"},{"prompt":"Which activity practices phoneme substitution?","correct":"Change the /m/ in “map” to /t/ and say the new word.","distractors":["Count the syllables in “map.”","Identify the printed letter m.","Repeat “map” three times."],"explanation":"Substitution replaces one phoneme with another, producing “tap.”"},{"prompt":"Which is a syllable-awareness task?","correct":"Clap once for each part in “computer.”","distractors":["Name the sound represented by c.","Read “computer” from a card.","Spell the word from dictation."],"explanation":"Syllable awareness involves larger spoken units than individual phonemes."},{"prompt":"Which pair rhymes?","correct":"light and kite","distractors":["light and late","kite and cat","late and let"],"explanation":"Rhyming words share the same ending sound from the vowel onward."},{"prompt":"The onset in the spoken word “stop” is:","correct":"/st/","distractors":["/op/","/t/","/sto/"],"explanation":"The onset includes consonant sounds before the vowel; the rime is /op/."},{"prompt":"The rime in the spoken word “stop” is:","correct":"/op/","distractors":["/st/","/s/","/top/"],"explanation":"The rime begins with the vowel and includes following sounds."},{"prompt":"Which sequence moves from larger to smaller units of spoken language?","correct":"Sentence → word → syllable → onset-rime → phoneme","distractors":["Phoneme → syllable → word → sentence only","Letter → page → phoneme → paragraph","Morpheme → book → sound → sentence"],"explanation":"Phonological awareness progresses across nested units, with phonemes the smallest in this sequence."},{"prompt":"A child can identify rhymes but cannot blend individual phonemes. What does this suggest?","correct":"The child has a larger-unit phonological skill but needs explicit work at the phoneme level.","distractors":["The child has mastered all phonics.","The child should skip directly to silent reading.","Rhyme awareness and phoneme blending are identical skills."],"explanation":"Rhyming is less demanding than blending individual sounds."},{"prompt":"Which word begins with the same phoneme as “giant”?","correct":"jar","distractors":["goat","kite","chair"],"explanation":"In “giant” and “jar,” g/j represent the /j/ sound."},{"prompt":"Which word ends with the same phoneme as “laugh”?","correct":"cuff","distractors":["leaf","love","lake"],"explanation":"“Laugh” and “cuff” end in /f/."},{"prompt":"Phonemic-awareness instruction is most effective when it is:","correct":"brief, explicit, systematic, and connected to letters as students are ready.","distractors":["limited to guessing words from pictures.","based only on memorizing letter names.","avoided once students enter kindergarten."],"explanation":"Research supports focused instruction in manipulating sounds, often strengthened by linking phonemes to graphemes."},{"prompt":"Which task is generally more advanced?","correct":"Changing /m/ in “smile” to /t/","distractors":["Recognizing that “cat” and “hat” rhyme","Clapping syllables in “sunset”","Identifying the first word in a sentence"],"explanation":"Phoneme substitution within a consonant cluster requires fine-grained manipulation."},{"prompt":"A student confuses the concepts of letters and sounds. Which statement is most accurate?","correct":"Letters are written symbols; phonemes are speech sounds that letters or letter groups represent.","distractors":["Every letter always represents exactly one phoneme.","Phonemes are printed marks only.","There are always equal numbers of letters and phonemes in a word."],"explanation":"English spelling represents sounds with graphemes, but the correspondence is not one-to-one."},{"prompt":"Which word has three syllables?","correct":"elephant","distractors":["sunset","train","map"],"explanation":"“Elephant” has three spoken syllables: el-e-phant; “sunset” has two and the others one."},{"prompt":"Which word contains a consonant blend in which both sounds are heard?","correct":"flag","distractors":["ship","chat","thin"],"explanation":"In /fl/, both /f/ and /l/ remain audible; sh, ch, and th are digraphs representing single phonemes in these words."}]},"el-phonics":{"label":"Phonics, Word Analysis, Spelling, and Morphology","description":"Grapheme–phoneme correspondences, syllable types, multisyllabic decoding, morphemes, roots, affixes, and orthographic mapping.","group":"Foundational Reading","questions":[{"prompt":"Which word contains a closed syllable?","correct":"cat","distractors":["me","boat","cube"],"explanation":"A closed syllable ends in a consonant and usually has a short vowel."},{"prompt":"Which word contains an open syllable?","correct":"he","distractors":["cat","fish","cup"],"explanation":"An open syllable ends in a vowel, which is typically long."},{"prompt":"Which word contains a vowel-consonant-e pattern?","correct":"hope","distractors":["hop","boat","coin"],"explanation":"In “hope,” final e helps signal the long vowel in the preceding syllable."},{"prompt":"Which word contains a vowel team?","correct":"rain","distractors":["ran","ride","robot"],"explanation":"The letters ai work together to represent a vowel sound."},{"prompt":"Which word contains an r-controlled vowel?","correct":"storm","distractors":["stone","steam","stop"],"explanation":"The vowel sound in “or” is influenced by r."},{"prompt":"Which word contains a consonant digraph?","correct":"chair","distractors":["clap","drum","flag"],"explanation":"The letters ch represent a single consonant phoneme; cl, dr, and fl are blends."},{"prompt":"Which word contains a consonant blend?","correct":"plant","distractors":["ship","thin","chop"],"explanation":"In pl, both consonant sounds are retained."},{"prompt":"Which division is most appropriate for the word “rabbit”?","correct":"rab-bit","distractors":["ra-bbit","rabb-it","r-abbit"],"explanation":"Between two consonants in a VCCV pattern, division commonly occurs between the consonants."},{"prompt":"Which word is most directly decoded using the common soft-c rule?","correct":"city","distractors":["cat","coat","cup"],"explanation":"C often represents /s/ before e, i, or y."},{"prompt":"Which word is most directly decoded using the common soft-g rule?","correct":"giant","distractors":["game","goat","gum"],"explanation":"G often represents /j/ before e, i, or y, though English has exceptions."},{"prompt":"The prefix “un-” usually means:","correct":"not or the opposite of.","distractors":["again.","before.","one who."],"explanation":"In words such as “unfair,” un- negates or reverses the base meaning."},{"prompt":"The suffix “-less” usually means:","correct":"without.","distractors":["full of.","one who.","in the past."],"explanation":"“Careless” means without sufficient care."},{"prompt":"Which word contains a Latin root meaning “see”?","correct":"inspect","distractors":["transport","audible","geology"],"explanation":"The root spect means “look” or “see.”"},{"prompt":"Which word contains a Greek root meaning “earth”?","correct":"geology","distractors":["biology","telephone","photograph"],"explanation":"Geo means earth; geology is the study of Earth."},{"prompt":"Which analysis best explains “preview”?","correct":"pre- means before, and view means see; preview means see beforehand.","distractors":["pre- means after, and view means write.","The word has no meaningful parts.","view is a suffix meaning person."],"explanation":"Morphological analysis combines meaningful word parts."},{"prompt":"A student reads “jumped” as /jump-ed/. Which concept needs clarification?","correct":"The inflection -ed can be pronounced /t/, /d/, or /əd/ depending on the base word.","distractors":["Every suffix forms a separate syllable.","J never represents /j/.","Past tense is shown only by word order."],"explanation":"In “jumped,” -ed is pronounced /t/ and does not add a syllable."},{"prompt":"Which word has an inflectional suffix?","correct":"dogs","distractors":["doghouse","dogma","underdog"],"explanation":"The plural -s changes grammatical number without creating a new lexical category."},{"prompt":"Which word has a derivational suffix?","correct":"happiness","distractors":["cats","jumped","taller"],"explanation":"-ness changes the adjective “happy” into a noun."},{"prompt":"Which spelling pattern represents the /ch/ sound in “nature”?","correct":"ture","distractors":["ch","tch","sh"],"explanation":"In many words, the sequence ture includes a /chər/ or /chə/ sound."},{"prompt":"Which word is irregular because it cannot be decoded fully by the most common correspondences?","correct":"said","distractors":["map","ship","cake"],"explanation":"“Said” contains an unexpected vowel spelling and is commonly taught as an irregular high-frequency word."},{"prompt":"Which practice best builds orthographic mapping?","correct":"Students connect phonemes in a spoken word to graphemes in its spelling while attending to meaning.","distractors":["Students memorize the overall visual shape of words.","Students guess from the first letter and picture.","Students repeatedly copy words without analyzing sounds."],"explanation":"Orthographic mapping bonds pronunciation, spelling, and meaning through phoneme–grapheme connections."},{"prompt":"Which word has two morphemes?","correct":"replay","distractors":["cat","blue","under"],"explanation":"“Replay” contains the prefix re- and the base play."},{"prompt":"Which word contains a schwa in an unstressed syllable?","correct":"about","distractors":["cat","team","bike"],"explanation":"The initial a in “about” is commonly pronounced as schwa /ə/."},{"prompt":"Why is syllable-type knowledge useful?","correct":"It helps readers predict vowel pronunciations and decode multisyllabic words.","distractors":["It eliminates every exception in English.","It replaces vocabulary knowledge.","It applies only to handwriting."],"explanation":"Syllable patterns provide useful, though not exception-free, decoding guidance."},{"prompt":"Which sequence is most appropriate for explicit phonics instruction?","correct":"Introduce a correspondence, model blending, practice in words, then apply it in decodable text.","distractors":["Begin with an uncontrolled novel and ask students to guess.","Teach all correspondences simultaneously.","Avoid cumulative review."],"explanation":"Explicit, systematic instruction moves from modeling to guided practice and connected-text application."}]},"el-fluency":{"label":"Reading Fluency","description":"Accuracy, automaticity, rate, prosody, repeated reading, phrase-cued reading, and fluency assessment.","group":"Foundational Reading","questions":[{"prompt":"Reading fluency includes:","correct":"accuracy, appropriate rate, and prosody.","distractors":["speed only.","comprehension only with no oral features.","memorizing page numbers."],"explanation":"Fluent reading is accurate, reasonably automatic, and expressive."},{"prompt":"Why does fluency support comprehension?","correct":"Automatic word recognition frees attention for constructing meaning.","distractors":["Fast reading guarantees deep understanding.","Fluency eliminates the need for vocabulary.","Comprehension occurs before recognizing words."],"explanation":"When decoding requires less effort, working memory can focus more on ideas and relationships."},{"prompt":"Which activity is supported for improving fluency?","correct":"Repeated oral reading of an appropriately challenging passage with feedback.","distractors":["Silent rereading with no monitoring in every case.","Reading text far beyond the student’s decoding level.","Timed speed drills that ignore accuracy and expression."],"explanation":"Guided repeated reading builds automaticity, accuracy, and prosody."},{"prompt":"A student reads rapidly but substitutes many words and cannot explain the passage. The primary concern is:","correct":"accuracy and comprehension, not insufficient speed.","distractors":["the student must read even faster.","prosody is the only issue.","the text is automatically mastered."],"explanation":"Rate is useful only when accuracy and meaning are maintained."},{"prompt":"Which practice best models prosody?","correct":"The teacher reads aloud, thinking about phrasing and expression, then students echo-read.","distractors":["Students whisper isolated letters.","The teacher reads every word with equal stress.","Students race without punctuation."],"explanation":"Modeling and echo reading make phrasing, stress, and intonation audible."},{"prompt":"Which punctuation mark most strongly signals a brief pause within a sentence?","correct":"Comma","distractors":["Apostrophe","Quotation mark alone","Hyphen"],"explanation":"A comma often marks a short syntactic pause, though phrasing ultimately follows meaning and structure."},{"prompt":"A student reads word by word with accurate decoding. Which support is most appropriate?","correct":"Phrase-cued reading and repeated reading of connected text.","distractors":["Return only to letter-name drills.","Increase text difficulty sharply.","Require faster reading without a model."],"explanation":"Phrase-cued practice helps combine words into meaningful syntactic units."},{"prompt":"Which assessment gives a quick measure of oral reading accuracy and rate?","correct":"A timed oral reading sample with errors recorded","distractors":["A spelling inventory only","A listening-comprehension interview only","A handwriting sample only"],"explanation":"Curriculum-based oral reading measures can estimate correct words per minute and error patterns."},{"prompt":"When interpreting words-correct-per-minute data, a teacher should also consider:","correct":"accuracy, prosody, comprehension, text difficulty, and growth over time.","distractors":["rate alone as a complete diagnosis.","the student’s handwriting.","only class rank."],"explanation":"Fluency is multidimensional, and a single rate score does not explain the cause of difficulty."},{"prompt":"Which text is most appropriate for initial repeated-reading practice?","correct":"A brief passage the student can decode with high accuracy but not yet automaticity","distractors":["A passage with many untaught patterns and frequent frustration","A page of random symbols","A text the student has memorized without reading print."],"explanation":"Practice should be accessible enough for successful attention to automaticity and phrasing."},{"prompt":"Choral reading can support fluency because:","correct":"students read a text together with a proficient model and reduced performance pressure.","distractors":["it prevents students from attending to print.","it measures individual accuracy precisely.","it replaces all individual assessment."],"explanation":"Choral reading offers supported practice but should be supplemented by individual observation."},{"prompt":"Which behavior is evidence of prosodic reading?","correct":"Pausing at meaningful phrase boundaries and varying intonation to match syntax and meaning","distractors":["Stopping after every word","Ignoring punctuation and dialogue","Reading with constant pitch and stress"],"explanation":"Prosody reflects grammatical structure and interpretation."},{"prompt":"A student’s decoding is accurate but slow because many words are not automatic. The best next step is:","correct":"cumulative practice reading words and connected text containing taught patterns.","distractors":["teach only comprehension strategies with no word reading.","ask the student to guess unfamiliar words from pictures.","avoid rereading."],"explanation":"Automaticity develops through accurate repeated encounters with well-taught spelling patterns."},{"prompt":"Which statement about silent reading is most accurate?","correct":"Independent silent reading is valuable, but students with weak decoding often need explicit instruction and guided oral practice too.","distractors":["Silent reading alone reliably remediates every decoding difficulty.","Oral reading never provides useful evidence.","Students should read only aloud."],"explanation":"Different purposes require a balanced approach matched to student needs."},{"prompt":"A teacher marks slashes in a sentence to show meaningful groups of words. This is called:","correct":"phrase-cued reading.","distractors":["phoneme deletion.","morpheme substitution.","alphabetic sorting."],"explanation":"Phrase cues help students see and practice syntactic grouping."}]},"el-vocabulary":{"label":"Vocabulary and Word Meaning","description":"Context, morphology, roots, connotation, academic vocabulary, reference tools, idioms, and deep word knowledge.","group":"Comprehension","questions":[{"prompt":"Which context clue is used in “Arid regions, or places with very little rainfall, require careful water management”?","correct":"Definition or restatement","distractors":["Antonym only","Example without explanation","Cause and effect only"],"explanation":"The phrase after “or” restates the meaning of arid."},{"prompt":"Which strategy best determines the meaning of “preview”?","correct":"Analyze the prefix pre- and base word view.","distractors":["Count the letters only.","Use the first sound to guess.","Ignore the sentence."],"explanation":"Morphemic analysis shows that pre- means before and view means see."},{"prompt":"In the sentence “The trail was arduous, requiring hours of steep climbing,” what does “arduous” most nearly mean?","correct":"difficult and demanding","distractors":["short and level","poorly marked","crowded"],"explanation":"The appositive phrase describes the trail as requiring great effort."},{"prompt":"Which pair consists of synonyms?","correct":"brief and concise","distractors":["ancient and modern","expand and contract","scarce and abundant"],"explanation":"Brief and concise both mean short in duration or expression."},{"prompt":"Which pair consists of antonyms?","correct":"scarce and abundant","distractors":["rapid and swift","observe and notice","fragile and delicate"],"explanation":"Scarce means limited; abundant means plentiful."},{"prompt":"Which word is a homophone of “their”?","correct":"there","distractors":["theory","thorough","three"],"explanation":"“Their” and “there” sound alike but differ in spelling and meaning."},{"prompt":"Which sentence uses “conduct” as a verb?","correct":"Scientists conduct repeated trials.","distractors":["The conductor praised professional conduct.","The code describes proper conduct.","Good conduct earns trust."],"explanation":"Here conduct means perform or carry out."},{"prompt":"The root “bio” most often means:","correct":"life.","distractors":["earth.","sound.","write."],"explanation":"Bio appears in words such as biology and biography."},{"prompt":"The root “aud” most often means:","correct":"hear.","distractors":["see.","carry.","measure."],"explanation":"Aud appears in audience and audible."},{"prompt":"The root “scrib/script” most often means:","correct":"write.","distractors":["move.","heat.","time."],"explanation":"Scribe, manuscript, and description share a root related to writing."},{"prompt":"Which word has the most positive connotation?","correct":"confident","distractors":["arrogant","conceited","bossy"],"explanation":"Confident suggests self-assurance without the negative judgment associated with the distractors."},{"prompt":"Which word has the most negative connotation?","correct":"stubborn","distractors":["determined","persistent","steadfast"],"explanation":"Stubborn often implies unreasonable refusal to change, whereas the others can be approving."},{"prompt":"Tier Two vocabulary consists mainly of:","correct":"high-utility academic words used across many subjects.","distractors":["only rare technical terms in one field.","basic everyday words known by most young children.","proper names."],"explanation":"Tier Two words such as analyze, contrast, and significant support comprehension across disciplines."},{"prompt":"Which is a Tier Three word in a science unit?","correct":"photosynthesis","distractors":["compare","important","because"],"explanation":"Photosynthesis is a domain-specific technical term."},{"prompt":"Which approach best develops deep word knowledge?","correct":"Provide student-friendly definitions, examples and nonexamples, morphological links, and repeated use in varied contexts.","distractors":["Assign one dictionary copy and never revisit the word.","Teach only pronunciation.","Present unrelated word lists with no context."],"explanation":"Multiple meaningful encounters build flexible knowledge of meaning, use, relationships, and word parts."},{"prompt":"Which reference source best shows a word’s origin and historical development?","correct":"An etymological dictionary","distractors":["A table of contents","An atlas","A thesaurus only"],"explanation":"Etymology traces a word’s source and changes across languages and time."},{"prompt":"A thesaurus is most useful for:","correct":"finding related words and considering shades of meaning.","distractors":["determining exact pronunciation only.","checking a historical date.","locating a place on a map."],"explanation":"A thesaurus offers synonyms and related terms, but writers must verify connotation and usage."},{"prompt":"Which statement about using context clues is most accurate?","correct":"Context can suggest meaning, but readers should combine it with morphology and reference tools when needed.","distractors":["Context always gives an exact definition.","Readers should ignore word parts.","Dictionary use is never appropriate."],"explanation":"No single strategy is sufficient for every unfamiliar word."},{"prompt":"In “The scientist’s explanation was plausible because it fit the available evidence,” plausible means:","correct":"reasonable or believable.","distractors":["certainly false.","unrelated.","impossible to test."],"explanation":"The causal phrase indicates that the explanation reasonably fits evidence."},{"prompt":"Which sentence best illustrates an idiom?","correct":"After weeks of practice, Maya knew the routine by heart.","distractors":["Maya’s heart pumps blood.","Maya read the directions.","Maya practiced for two weeks."],"explanation":"“By heart” means from memory rather than literally using the heart."}]},"el-literary":{"label":"Literary Text Comprehension and Analysis","description":"Theme, inference, characterization, point of view, figurative language, structure, mood, conflict, and poetry.","group":"Text Analysis","questions":[{"prompt":"What theme is best supported by the passage?","correct":"Small acts of care can help neglected places change.","distractors":["Nature always succeeds without human help.","Secrets inevitably cause conflict.","Traveling home is dangerous."],"explanation":"Nia quietly tends the flowers, suggesting that modest care can nurture change.","stimulus":"<h3>The Empty Lot</h3><p>Every afternoon, Nia cut through the empty lot on her way home. In March it was a patchwork of mud and bottle caps. By May, however, sunflowers had pushed through the hard ground. Nia began carrying a jar of water in her backpack. She never told anyone why.</p>"},{"prompt":"Why does the author mention the bottle caps?","correct":"To emphasize the lot’s neglect before the sunflowers grew","distractors":["To show Nia collected glass for money","To explain why flowers cannot grow","To introduce another character"],"explanation":"The litter creates a contrast with the later growth and Nia’s care.","stimulus":"<h3>The Empty Lot</h3><p>Every afternoon, Nia cut through the empty lot on her way home. In March it was a patchwork of mud and bottle caps. By May, however, sunflowers had pushed through the hard ground. Nia began carrying a jar of water in her backpack. She never told anyone why.</p>"},{"prompt":"What can the reader infer about the jar of water?","correct":"Nia uses it to water the sunflowers.","distractors":["Nia plans to drink it all before class.","Nia is conducting a chemistry experiment.","Nia wants to wash bottle caps."],"explanation":"The timing and her secrecy connect the water to the plants she has noticed.","stimulus":"<h3>The Empty Lot</h3><p>Every afternoon, Nia cut through the empty lot on her way home. In March it was a patchwork of mud and bottle caps. By May, however, sunflowers had pushed through the hard ground. Nia began carrying a jar of water in her backpack. She never told anyone why.</p>"},{"prompt":"Which trait does Mr. Vale demonstrate most clearly?","correct":"Patience","distractors":["Jealousy","Carelessness","Fearfulness"],"explanation":"He treats the error as an opportunity for careful observation rather than reacting angrily.","stimulus":"<h3>The Clockmaker</h3><p>Mr. Vale repaired clocks in a shop where every wall ticked at a slightly different pace. “A clock does not hurry,” he told his apprentice, Lena. “It repeats the next careful step.” When Lena bent a tiny spring, she expected him to scold her. Instead, he placed a magnifying lens beside her hand and said, “Now we learn where it resists.”</p>"},{"prompt":"The statement “A clock does not hurry” mainly conveys the idea that:","correct":"precise work requires steady attention to each step.","distractors":["clocks cannot be repaired.","time passes differently in the shop.","Lena should work as slowly as possible in every situation."],"explanation":"The clock becomes a metaphor for deliberate, methodical work.","stimulus":"<h3>The Clockmaker</h3><p>Mr. Vale repaired clocks in a shop where every wall ticked at a slightly different pace. “A clock does not hurry,” he told his apprentice, Lena. “It repeats the next careful step.” When Lena bent a tiny spring, she expected him to scold her. Instead, he placed a magnifying lens beside her hand and said, “Now we learn where it resists.”</p>"},{"prompt":"Why does Mr. Vale provide a magnifying lens?","correct":"To help Lena examine the cause of the problem","distractors":["To replace the damaged clock","To punish Lena with more work","To show that he cannot see"],"explanation":"He guides her toward evidence and learning from the mistake.","stimulus":"<h3>The Clockmaker</h3><p>Mr. Vale repaired clocks in a shop where every wall ticked at a slightly different pace. “A clock does not hurry,” he told his apprentice, Lena. “It repeats the next careful step.” When Lena bent a tiny spring, she expected him to scold her. Instead, he placed a magnifying lens beside her hand and said, “Now we learn where it resists.”</p>"},{"prompt":"Which mood is created by the imagery?","correct":"A mixture of wonder and uncertainty","distractors":["Comic excitement","Angry confrontation","Complete boredom"],"explanation":"The fleeting lights are beautiful, while Tomas’s attempt to memorize them and unknown destination create uncertainty.","stimulus":"<h3>Night Train</h3><p>The train crossed the prairie after midnight. Towns appeared as brief necklaces of light, then vanished behind the glass. Tomas pressed his forehead to the window, trying to memorize each one. By morning, he would arrive in a city he knew only from his sister’s letters.</p>"},{"prompt":"The phrase “necklaces of light” is an example of:","correct":"metaphor.","distractors":["alliteration only.","literal definition.","irony."],"explanation":"The towns’ lights are directly compared to necklaces without using like or as.","stimulus":"<h3>Night Train</h3><p>The train crossed the prairie after midnight. Towns appeared as brief necklaces of light, then vanished behind the glass. Tomas pressed his forehead to the window, trying to memorize each one. By morning, he would arrive in a city he knew only from his sister’s letters.</p>"},{"prompt":"What motivates Tomas to study the towns?","correct":"He is leaving familiar places and wants to remember the journey.","distractors":["He plans to count every streetlight for work.","He dislikes his sister’s letters.","He is searching for a lost necklace."],"explanation":"His attention to the passing towns reflects the significance of entering an unfamiliar future.","stimulus":"<h3>Night Train</h3><p>The train crossed the prairie after midnight. Towns appeared as brief necklaces of light, then vanished behind the glass. Tomas pressed his forehead to the window, trying to memorize each one. By morning, he would arrive in a city he knew only from his sister’s letters.</p>"},{"prompt":"Which characterization method is used most strongly?","correct":"Leah is revealed through her actions and choices.","distractors":["The narrator directly lists all her traits.","Another character gives a long description.","The setting speaks about her."],"explanation":"Her adjustments and decision to continue show persistence without directly naming it.","stimulus":"<h3>Borrowed Boots</h3><p>Leah’s borrowed hiking boots were one size too large. At the first hill, her heels slipped. At the second, a blister began. When the trail guide offered to turn back with her, Leah tightened the laces, added a second pair of socks, and continued at the rear of the group.</p>"},{"prompt":"Which word best describes Leah?","correct":"Resourceful","distractors":["Indifferent","Dishonest","Reckless"],"explanation":"She adapts with tighter laces and extra socks rather than simply giving up.","stimulus":"<h3>Borrowed Boots</h3><p>Leah’s borrowed hiking boots were one size too large. At the first hill, her heels slipped. At the second, a blister began. When the trail guide offered to turn back with her, Leah tightened the laces, added a second pair of socks, and continued at the rear of the group.</p>"},{"prompt":"What conflict is central to the passage?","correct":"Leah struggles against physical discomfort while trying to complete the hike.","distractors":["Leah argues with the guide about directions.","The group is lost in a storm.","Leah wants to return borrowed money."],"explanation":"The problem is person versus physical circumstances and her own desire to continue.","stimulus":"<h3>Borrowed Boots</h3><p>Leah’s borrowed hiking boots were one size too large. At the first hill, her heels slipped. At the second, a blister began. When the trail guide offered to turn back with her, Leah tightened the laces, added a second pair of socks, and continued at the rear of the group.</p>"},{"prompt":"The poem primarily uses:","correct":"personification and sound imagery.","distractors":["historical allusion.","formal argument.","literal scientific definition."],"explanation":"The storm “assembles” an orchestra, while drum, flutes, and taps evoke sounds.","stimulus":"<h3>Rain Recipe</h3><p><em>One roof drum,<br>two gutter flutes,<br>a thousand window taps—<br>the storm assembles<br>its kitchen orchestra.</em></p>"},{"prompt":"What is the effect of the phrase “kitchen orchestra”?","correct":"It transforms familiar household rain sounds into music.","distractors":["It proves musicians are cooking.","It explains how storms form.","It creates a legal claim."],"explanation":"The metaphor invites readers to hear ordinary surfaces as instruments.","stimulus":"<h3>Rain Recipe</h3><p><em>One roof drum,<br>two gutter flutes,<br>a thousand window taps—<br>the storm assembles<br>its kitchen orchestra.</em></p>"},{"prompt":"Which sense is emphasized most?","correct":"Hearing","distractors":["Taste","Smell","Touch"],"explanation":"The poem names drums, flutes, and taps, all associated with sound.","stimulus":"<h3>Rain Recipe</h3><p><em>One roof drum,<br>two gutter flutes,<br>a thousand window taps—<br>the storm assembles<br>its kitchen orchestra.</em></p>"},{"prompt":"Which narrative point of view uses “I” and presents events through a participating character?","correct":"First-person point of view","distractors":["Third-person omniscient","Second-person instructional only","Objective documentary voice only"],"explanation":"First-person narrators use I or we and participate in or directly observe events."},{"prompt":"A third-person omniscient narrator can:","correct":"reveal the thoughts and feelings of multiple characters.","distractors":["use only dialogue with no narration.","describe only what one character knows.","never comment on events."],"explanation":"Omniscient narration has access to more than one character’s inner experience."},{"prompt":"Dramatic irony occurs when:","correct":"the audience knows important information that a character does not.","distractors":["a character says exactly what is meant.","a poem repeats consonant sounds.","the setting changes suddenly."],"explanation":"The gap between audience knowledge and character knowledge creates tension or humor."},{"prompt":"A symbol in literature is:","correct":"a concrete object, character, or event that carries meaning beyond its literal role.","distractors":["a spelling error.","a direct dictionary definition only.","a sentence with no imagery."],"explanation":"Symbols operate literally within a text while suggesting broader ideas."},{"prompt":"Which statement best distinguishes theme from summary?","correct":"Theme expresses a broader insight; summary recounts the text’s main events or ideas.","distractors":["Theme lists every event.","Summary is always one word.","They are identical."],"explanation":"A theme generalizes the text’s meaning, while a summary condenses content."}]},"el-informational":{"label":"Informational and Argumentative Text","description":"Central ideas, evidence, text structure, argument, source credibility, data displays, summary, paraphrase, and counterclaims.","group":"Text Analysis","questions":[{"prompt":"What is the central idea?","correct":"Urban trees provide several benefits, but successful programs require careful selection and maintenance.","distractors":["All tree species are equally suitable for cities.","Trees are useful only for decoration.","Sidewalk damage is the main purpose of urban forestry."],"explanation":"The paragraph balances benefits with the need for planning and care.","stimulus":"<h3>City Trees</h3><p>Trees along city streets provide more than shade. Their leaves intercept rainfall, and their roots help water soak into soil. Trees can also reduce nearby air temperatures through shade and evaporation. However, poorly chosen species may damage sidewalks or fail during drought. Successful urban forestry therefore depends on selecting appropriate trees and maintaining them over time.</p>"},{"prompt":"Which text structure is used most clearly?","correct":"Benefits followed by a qualification or problem-solution consideration","distractors":["Chronological biography","Compare two historical wars","A fictional plot with conflict"],"explanation":"The author lists benefits, identifies possible problems, and states what successful practice requires.","stimulus":"<h3>City Trees</h3><p>Trees along city streets provide more than shade. Their leaves intercept rainfall, and their roots help water soak into soil. Trees can also reduce nearby air temperatures through shade and evaporation. However, poorly chosen species may damage sidewalks or fail during drought. Successful urban forestry therefore depends on selecting appropriate trees and maintaining them over time.</p>"},{"prompt":"Which detail best supports the claim that trees can help manage stormwater?","correct":"Leaves intercept rainfall and roots help water soak into soil.","distractors":["Trees can damage sidewalks.","Species must be selected.","Trees may fail in drought."],"explanation":"That sentence directly explains two mechanisms that affect runoff.","stimulus":"<h3>City Trees</h3><p>Trees along city streets provide more than shade. Their leaves intercept rainfall, and their roots help water soak into soil. Trees can also reduce nearby air temperatures through shade and evaporation. However, poorly chosen species may damage sidewalks or fail during drought. Successful urban forestry therefore depends on selecting appropriate trees and maintaining them over time.</p>"},{"prompt":"The author’s main purpose is to:","correct":"present competing considerations and recommend weighing local evidence.","distractors":["argue that every district must change immediately.","describe a fictional school day.","prove transportation has no cost."],"explanation":"The paragraph summarizes both sides and calls for context-specific evaluation.","stimulus":"<h3>School Start Times</h3><p>Some districts have moved secondary-school start times later. Supporters point to research on adolescent sleep cycles and report improvements in attendance and alertness. Opponents note that transportation schedules, athletics, and family routines may become more complicated. Any district considering a change should compare likely health benefits with local logistical costs.</p>"},{"prompt":"Which statement is evidence offered by supporters?","correct":"Later starts may improve attendance and alertness.","distractors":["Athletics always become impossible.","Every family prefers earlier starts.","Transportation schedules never change."],"explanation":"The passage attributes reported improvements in attendance and alertness to supporters.","stimulus":"<h3>School Start Times</h3><p>Some districts have moved secondary-school start times later. Supporters point to research on adolescent sleep cycles and report improvements in attendance and alertness. Opponents note that transportation schedules, athletics, and family routines may become more complicated. Any district considering a change should compare likely health benefits with local logistical costs.</p>"},{"prompt":"Which additional evidence would be most useful to a district?","correct":"Local data on student sleep, transportation costs, attendance, and after-school participation","distractors":["A national mascot survey","One anonymous comment with no context","The color of school buses"],"explanation":"The decision involves health and logistical trade-offs that local data can illuminate.","stimulus":"<h3>School Start Times</h3><p>Some districts have moved secondary-school start times later. Supporters point to research on adolescent sleep cycles and report improvements in attendance and alertness. Opponents note that transportation schedules, athletics, and family routines may become more complicated. Any district considering a change should compare likely health benefits with local logistical costs.</p>"},{"prompt":"Which relationship does the passage explain?","correct":"Features of the dance communicate direction and distance to food.","distractors":["Bee color determines the weather.","Odor cues replace all movement.","The Sun provides food inside the hive."],"explanation":"The passage maps dance direction and duration to spatial information.","stimulus":"<h3>How Bees Communicate</h3><p>A honeybee returning from a rich food source may perform a waggle dance. The direction of the central run relates to the food’s direction relative to the Sun, while the duration conveys information about distance. Other bees combine the dance with odor cues before leaving the hive.</p>"},{"prompt":"What does “while” signal in the second sentence?","correct":"A contrast or parallel between two different features and meanings","distractors":["A chronological gap of several years","A cause with no second idea","A definition of honey"],"explanation":"The conjunction coordinates two simultaneous correspondences: direction and duration.","stimulus":"<h3>How Bees Communicate</h3><p>A honeybee returning from a rich food source may perform a waggle dance. The direction of the central run relates to the food’s direction relative to the Sun, while the duration conveys information about distance. Other bees combine the dance with odor cues before leaving the hive.</p>"},{"prompt":"Which summary is best?","correct":"Honeybees use a dance, together with odor, to share the location of food.","distractors":["Honeybees never leave the hive.","A waggle dance is performed only at night.","All insects communicate in the same way."],"explanation":"The summary captures the main mechanism without unnecessary detail.","stimulus":"<h3>How Bees Communicate</h3><p>A honeybee returning from a rich food source may perform a waggle dance. The direction of the central run relates to the food’s direction relative to the Sun, while the duration conveys information about distance. Other bees combine the dance with odor cues before leaving the hive.</p>"},{"prompt":"Which claim is most strongly supported?","correct":"The proposal has potential community benefits but requires additional cost and feasibility analysis.","distractors":["The studio is certain to pay for itself.","The storage room is currently the busiest room.","No grant funding exists."],"explanation":"The passage lists possible benefits and specific questions that must be answered.","stimulus":"<h3>Library Proposal</h3><p>The town library proposes converting a rarely used storage room into a small recording studio. The studio could support oral-history projects, student podcasts, and accessible audiobook production. The renovation would cost $18,000. Before approving the plan, the council should examine projected use, staffing needs, soundproofing costs, and whether grants could reduce local expense.</p>"},{"prompt":"Which detail is a verifiable quantitative fact within the proposal?","correct":"The stated renovation estimate is $18,000.","distractors":["The studio will be wonderful.","Podcasts are the best medium.","The council should be excited."],"explanation":"The dollar amount is a numerical claim that can be checked against estimates.","stimulus":"<h3>Library Proposal</h3><p>The town library proposes converting a rarely used storage room into a small recording studio. The studio could support oral-history projects, student podcasts, and accessible audiobook production. The renovation would cost $18,000. Before approving the plan, the council should examine projected use, staffing needs, soundproofing costs, and whether grants could reduce local expense.</p>"},{"prompt":"Which source would best verify projected demand?","correct":"A survey and usage study of likely community users","distractors":["A studio-equipment advertisement only","One council member’s preference","A list of unrelated library books"],"explanation":"Demand should be estimated from representative evidence about intended users.","stimulus":"<h3>Library Proposal</h3><p>The town library proposes converting a rarely used storage room into a small recording studio. The studio could support oral-history projects, student podcasts, and accessible audiobook production. The renovation would cost $18,000. Before approving the plan, the council should examine projected use, staffing needs, soundproofing costs, and whether grants could reduce local expense.</p>"},{"prompt":"Which statement is a claim rather than evidence?","correct":"The city should add protected bicycle lanes on major routes.","distractors":["A traffic count recorded 620 bicycles at the intersection last Tuesday.","Hospital records show 18 cycling injuries in the corridor last year.","The project estimate lists a cost of $2.1 million."],"explanation":"A claim advocates a conclusion; the other statements are data that might support or challenge it."},{"prompt":"Which source is generally most credible for a current public-health statistic?","correct":"A recent report from a responsible government health agency that explains its methods","distractors":["An anonymous social-media post","An advertisement selling a treatment","A chain message with no source"],"explanation":"Credibility depends on expertise, transparent methods, relevant data, and accountability."},{"prompt":"What is the purpose of a counterclaim in an argument?","correct":"To acknowledge and respond to a reasonable opposing position","distractors":["To repeat the main claim verbatim","To replace all evidence with emotion","To change the subject"],"explanation":"Addressing counterclaims strengthens reasoning by engaging alternatives."},{"prompt":"Which sentence uses cause-and-effect organization?","correct":"Because drought reduced the reservoir, the city adopted new watering restrictions.","distractors":["The reservoir has two boat ramps.","First, inspect the valve; next, close it.","The red tank is larger than the blue tank."],"explanation":"The sentence explicitly links drought as a cause to restrictions as an effect."},{"prompt":"Which text feature most directly helps a reader locate a specific topic in a long book?","correct":"Index","distractors":["Dedication","Epigraph","Copyright date"],"explanation":"An index lists topics and corresponding page numbers."},{"prompt":"A graph begins its vertical axis at 98 rather than 0, making a change from 99 to 100 appear enormous. The best evaluation is:","correct":"The graph may visually exaggerate a small difference, so readers should inspect the scale.","distractors":["The data must be false.","All truncated axes are unethical in every context.","The labels do not matter."],"explanation":"A truncated scale can be legitimate but can also distort visual impressions if not read carefully."},{"prompt":"Which statement best distinguishes paraphrase from summary?","correct":"A paraphrase restates a specific passage at similar detail; a summary condenses the main ideas.","distractors":["A paraphrase copies exactly.","A summary must include every example.","Both require no citation."],"explanation":"Both use new wording and generally require source acknowledgment, but they differ in scope and compression."},{"prompt":"Plagiarism occurs when a writer:","correct":"uses another person’s words or ideas without appropriate acknowledgment.","distractors":["quotes and cites accurately.","summarizes common knowledge.","develops an original claim from cited evidence."],"explanation":"Source use requires attribution for borrowed wording and distinctive ideas."},{"prompt":"Which transition most clearly signals contrast?","correct":"however","distractors":["therefore","for example","similarly"],"explanation":"However signals a shift to an opposing or qualifying idea."},{"prompt":"Which transition most clearly signals a result?","correct":"therefore","distractors":["meanwhile","in contrast","for instance"],"explanation":"Therefore introduces a conclusion or consequence derived from prior information."}]},"el-writing":{"label":"Writing Process and Composition","description":"Planning, thesis and claim development, organization, evidence, elaboration, revision, tone, narrative craft, feedback, and source integration.","group":"Written Communication","questions":[{"prompt":"Which step belongs primarily to revision rather than editing?","correct":"Reorganizing paragraphs to strengthen the development of the central idea","distractors":["Correcting a misspelled word","Adding a missing comma","Fixing subject–verb agreement"],"explanation":"Revision improves ideas, organization, and clarity; editing corrects conventions."},{"prompt":"Which step belongs primarily to editing?","correct":"Correcting punctuation and agreement errors","distractors":["Changing the thesis after examining evidence","Adding an example to develop a point","Reordering sections for coherence"],"explanation":"Editing focuses on correctness and surface conventions."},{"prompt":"Which thesis is most specific and arguable?","correct":"The city should expand bus service on weekends because current schedules limit access to work, shopping, and medical care.","distractors":["Buses exist in many cities.","Transportation is a topic.","Weekend service."],"explanation":"A strong thesis makes a clear claim and previews reasons."},{"prompt":"Which sentence is the best topic sentence for a paragraph about community gardens?","correct":"Community gardens can strengthen neighborhoods by providing food, shared space, and educational opportunities.","distractors":["Tomatoes grow in summer.","The garden has a green fence.","Yesterday was warm."],"explanation":"The sentence states a controlling idea broad enough for supporting details."},{"prompt":"Which supporting detail is most relevant to a claim that a school garden can support science learning?","correct":"Students can measure plant growth and analyze how light and water affect development.","distractors":["The fence could be painted blue.","The principal likes tomatoes.","The garden is near the parking lot."],"explanation":"The detail identifies an authentic scientific investigation."},{"prompt":"Which organizational pattern is most appropriate for explaining how to conduct an experiment?","correct":"Chronological or process order","distractors":["Random order","Spatial order only","Problem-solution with no steps"],"explanation":"Procedures should present actions in the sequence they are performed."},{"prompt":"Which organizational pattern is most appropriate for analyzing similarities and differences between two novels?","correct":"Compare and contrast","distractors":["Chronological procedure","Cause and effect only","Definition only"],"explanation":"Comparison organizes shared and differing features across texts."},{"prompt":"Which sentence provides the strongest evidence-based elaboration?","correct":"The attendance report shows a 12 percent decline in absences after the schedule change, suggesting that the new start time may have improved attendance.","distractors":["The schedule is obviously perfect.","Everyone knows students dislike mornings.","The report has numbers."],"explanation":"The sentence cites specific evidence and explains how it relates to the claim without overstating certainty."},{"prompt":"Which revision improves coherence between paragraphs?","correct":"Add a transition that explains how the second paragraph extends or contrasts with the first.","distractors":["Change every verb to past tense.","Add an unrelated quotation.","Remove all topic sentences."],"explanation":"Coherence depends on explicit, logical relationships among ideas."},{"prompt":"Which sentence uses a formal academic tone?","correct":"The results indicate that the treatment had a modest effect on growth.","distractors":["The treatment was super awesome.","You know, the plants got huge-ish.","That stuff totally worked."],"explanation":"Academic tone favors precise, measured language."},{"prompt":"Which introduction best engages readers without making an unsupported claim?","correct":"Each morning, hundreds of commuters wait at stops where buses arrive only once an hour; the proposed schedule would double service during peak periods.","distractors":["This is the greatest transportation plan in history.","Everyone agrees the buses are terrible.","Buses are buses."],"explanation":"The introduction uses a concrete situation and relevant detail while avoiding exaggeration."},{"prompt":"Which conclusion best synthesizes an argument?","correct":"By reducing wait times and connecting more workers to weekend shifts, expanded service would address both mobility and economic access.","distractors":["In conclusion, buses are vehicles.","I have now told you my opinion.","The end."],"explanation":"A synthesis returns to the central claim and shows how the reasons work together."},{"prompt":"Audience awareness most directly affects a writer’s choices about:","correct":"tone, background information, vocabulary, and examples.","distractors":["whether words have letters.","the direction of print.","the existence of paragraphs."],"explanation":"Writers adapt explanation and style to what readers know and need."},{"prompt":"Which peer-feedback comment is most useful?","correct":"Your claim is clear, but paragraph two needs evidence showing how the policy affects costs.","distractors":["Good job.","I do not like it.","Make it longer."],"explanation":"Specific feedback identifies a strength, a need, and the reasoning behind the suggestion."},{"prompt":"Which sentence best integrates a quotation?","correct":"The report warns that the bridge has “significant structural deterioration,” supporting the need for prompt inspection.","distractors":["“Significant structural deterioration.”","The report quote is there.","The bridge, quote, significant structural deterioration."],"explanation":"The quotation is introduced grammatically and its relevance is explained."},{"prompt":"Which practice best avoids plagiarism while taking notes?","correct":"Clearly distinguish direct quotations, paraphrases, and personal ideas and record source information immediately.","distractors":["Copy passages without quotation marks.","Wait until the final draft to guess sources.","Change a few words and omit citation."],"explanation":"Accurate note labeling prevents accidental source misuse."},{"prompt":"Which sentence contains the most precise verb?","correct":"The committee postponed the vote until it received the cost estimate.","distractors":["The committee did something with the vote.","The committee had the vote.","The committee was about the vote."],"explanation":"“Postponed” communicates the exact action."},{"prompt":"Which revision removes redundancy?","correct":"Replace “the final outcome at the end” with “the outcome.”","distractors":["Add “completely final outcome at the very end.”","Repeat the phrase in the next sentence.","Change “outcome” to “result outcome.”"],"explanation":"Final and at the end repeat meaning already contained in outcome."},{"prompt":"A narrative climax is the point at which:","correct":"the central conflict reaches its greatest intensity or decisive turning point.","distractors":["the setting is first introduced.","minor characters are listed.","the title is selected."],"explanation":"The climax is the peak of dramatic tension before resolution."},{"prompt":"Which detail most effectively shows rather than tells that a character is nervous?","correct":"He folded and unfolded the corner of the note while watching the door.","distractors":["He was nervous.","Nervousness is a feeling.","The room had a chair."],"explanation":"Observable behavior allows readers to infer the emotion."}]},"el-grammar":{"label":"Grammar, Usage, Mechanics, and Sentence Structure","description":"Agreement, pronouns, tense, modifiers, parallelism, sentence boundaries, punctuation, capitalization, and commonly confused words.","group":"Written Communication","questions":[{"prompt":"Which sentence has correct subject–verb agreement?","correct":"The collection of old maps belongs to the library.","distractors":["The collection of old maps belong to the library.","The maps in the collection belongs to the library.","The collection belong to the library."],"explanation":"The subject is singular “collection,” so the verb is “belongs.”"},{"prompt":"Which sentence correctly uses a subject pronoun in a compound subject?","correct":"Maria and I presented the project.","distractors":["Maria and me presented the project.","Me and Maria presented the project.","Maria and myself presented the project."],"explanation":"The compound subject requires the subject pronoun I."},{"prompt":"Which sentence correctly uses an object pronoun after a preposition?","correct":"The coach spoke to Jamal and me.","distractors":["The coach spoke to Jamal and I.","The coach spoke to I and Jamal.","The coach spoke to Jamal and myself."],"explanation":"The pronoun is the object of the preposition to, so “me” is correct."},{"prompt":"Which sentence maintains consistent verb tense?","correct":"Lena opened the box and examined the contents.","distractors":["Lena opened the box and examines the contents.","Lena opens the box and examined the contents.","Lena had open the box and examines it."],"explanation":"Both coordinated actions are expressed in the past tense."},{"prompt":"Which sentence is punctuated correctly?","correct":"After the storm ended, the crew inspected the bridge.","distractors":["After the storm ended the crew, inspected the bridge.","After the storm ended the crew inspected, the bridge.","After, the storm ended the crew inspected the bridge."],"explanation":"An introductory dependent clause is followed by a comma."},{"prompt":"Which sentence uses a semicolon correctly?","correct":"The rain stopped; the river continued to rise.","distractors":["The rain; stopped the river continued to rise.","The rain stopped; because the storm moved east.","The rain stopped,; the river rose."],"explanation":"A semicolon can join closely related independent clauses."},{"prompt":"Which sentence uses a colon correctly?","correct":"The kit contains three tools: a compass, a ruler, and a protractor.","distractors":["The kit: contains three tools.","The kit contains: three tools.","The kit contains three: tools a compass."],"explanation":"A colon follows a complete clause and introduces the list."},{"prompt":"Which sentence uses an apostrophe correctly?","correct":"The students’ projects filled the hallway.","distractors":["The students projects filled the hallway.","The student’s projects filled the hallway, when many students made them.","The students’s projects filled the hallway."],"explanation":"The plural possessive of students places the apostrophe after s."},{"prompt":"Which sentence correctly shows that one student owns the notebook?","correct":"The student’s notebook is missing.","distractors":["The students notebook is missing.","The students’ notebook is missing, if there is only one student.","The students’s notebook is missing."],"explanation":"A singular possessive noun takes apostrophe-s."},{"prompt":"Which sentence avoids a comma splice?","correct":"The museum closed early, so we returned on Saturday.","distractors":["The museum closed early, we returned on Saturday.","The museum closed early, returned Saturday.","The museum, closed early we returned on Saturday."],"explanation":"A coordinating conjunction with a comma correctly joins the independent clauses."},{"prompt":"Which is a complete sentence?","correct":"Because the road was flooded, the bus took another route.","distractors":["Because the road was flooded.","Taking another route through town.","Although the bus."],"explanation":"The sentence includes a dependent clause and a complete independent clause."},{"prompt":"Which revision corrects the run-on sentence “The bell rang the students remained seated”?","correct":"The bell rang, but the students remained seated.","distractors":["The bell rang, the students remained seated.","The bell rang the students, remained seated.","The bell, rang the students remained seated."],"explanation":"A comma plus coordinating conjunction correctly links the independent clauses."},{"prompt":"Which sentence places the modifier clearly?","correct":"Walking through the museum, Priya noticed a cracked frame.","distractors":["Walking through the museum, the cracked frame caught Priya’s attention.","Priya noticed, walking, a cracked frame through the museum.","The museum walking through Priya noticed a frame."],"explanation":"The introductory phrase logically modifies Priya, the person walking."},{"prompt":"Which sentence uses parallel structure?","correct":"The internship requires filing records, answering calls, and preparing reports.","distractors":["The internship requires filing records, to answer calls, and reports.","The internship requires files, answering, and to prepare reports.","The internship requires to file, answering calls, and report preparation."],"explanation":"All three items use parallel gerund phrases."},{"prompt":"Which sentence uses the comparative form correctly?","correct":"This route is shorter than the coastal route.","distractors":["This route is more shorter than the coastal route.","This route is shortest than the coastal route.","This route is most short than the coastal route."],"explanation":"Shorter is the correct comparative form for two routes."},{"prompt":"Which sentence uses the superlative form correctly?","correct":"Of the three routes, the mountain route is the shortest.","distractors":["Of the three routes, the mountain route is shorter.","The mountain route is most shortest.","The mountain route is more short."],"explanation":"The superlative “shortest” compares one item with a group of three or more."},{"prompt":"Which sentence uses capitalization correctly?","correct":"We visited the Gulf of Mexico in July.","distractors":["We visited the gulf of mexico in july.","We visited the Gulf Of Mexico in July.","We visited the gulf of Mexico in july."],"explanation":"Proper names and months are capitalized; short prepositions within geographic names are generally lowercase."},{"prompt":"Which sentence punctuates dialogue correctly?","correct":"“Please close the gate,” Elena said.","distractors":["“Please close the gate” Elena said.","“Please close the gate”, Elena said.","Please close the gate,” Elena said."],"explanation":"The comma belongs inside the closing quotation mark before the dialogue tag."},{"prompt":"Which sentence uses “its” and “it’s” correctly?","correct":"The robot lost its balance, but it’s working again.","distractors":["The robot lost it’s balance, but its working again.","The robot lost its balance, but its working again.","The robot lost it’s balance, but it’s working again."],"explanation":"Its is possessive; it’s is the contraction for it is."},{"prompt":"Which sentence uses “their,” “there,” and “they’re” correctly?","correct":"They’re placing their backpacks over there.","distractors":["Their placing they’re backpacks over there.","They’re placing there backpacks over their.","There placing their backpacks over they’re."],"explanation":"They’re means they are, their is possessive, and there refers to a place."},{"prompt":"Which sentence uses “fewer” correctly?","correct":"Fewer cars entered the parking lot today.","distractors":["Less cars entered today.","Fewer traffic entered today.","Less students entered today."],"explanation":"Fewer modifies countable plural nouns such as cars."},{"prompt":"Which sentence uses “less” correctly?","correct":"The tank contains less water than yesterday.","distractors":["The tank contains fewer water.","The tank contains less bottles.","There are less gallons in the tank."],"explanation":"Less modifies a mass noun such as water; fewer generally modifies countable items."},{"prompt":"Which sentence uses active voice?","correct":"The committee approved the proposal.","distractors":["The proposal was approved by the committee.","The proposal had been being approved.","Approval was given to the proposal."],"explanation":"In active voice, the subject performs the action."},{"prompt":"Which sentence is punctuated correctly with a nonessential phrase?","correct":"Dr. Chen, the new director, will speak tonight.","distractors":["Dr. Chen the new director will speak tonight.","Dr. Chen, the new director will speak tonight.","Dr. Chen the new director, will speak tonight."],"explanation":"The appositive “the new director” is nonessential and should be enclosed by commas."},{"prompt":"Which sentence correctly uses a coordinating conjunction?","correct":"We could walk to the station, or we could take the bus.","distractors":["We could walk to the station or, we could take the bus.","We could walk, to the station or we could take the bus.","We could walk to the station, because or take the bus."],"explanation":"A comma precedes or when it joins two independent clauses."}]},"el-research":{"label":"Research, Media Literacy, and Source Use","description":"Research questions, search, credibility, lateral reading, note-taking, citation, copyright, synthesis, graphs, and infographics.","group":"Inquiry and Media","questions":[{"prompt":"Which research question is most focused?","correct":"How did the 1900 Galveston hurricane change building and seawall policies in the city?","distractors":["What is history?","What happened in Texas?","Are hurricanes bad?"],"explanation":"The question identifies a specific event, place, and type of change."},{"prompt":"Which source is a primary source for studying a city council decision?","correct":"The official minutes from the meeting","distractors":["A textbook written decades later","A student’s unsourced summary","A general encyclopedia article"],"explanation":"Minutes created as part of the event are direct documentary evidence."},{"prompt":"Which source is most useful for a current scientific claim?","correct":"A recent peer-reviewed review article that explains evidence and methods","distractors":["An undated anonymous blog","A product advertisement","A fictional story"],"explanation":"Recency, expertise, peer review, and methodological transparency support credibility."},{"prompt":"What does lateral reading involve?","correct":"Leaving a site to investigate the source through independent, credible information","distractors":["Reading only the site’s “About” page","Scanning from left to right","Accepting the first search result"],"explanation":"Lateral reading checks reputation, ownership, expertise, and prior verification elsewhere."},{"prompt":"Which search query is most efficient for a focused inquiry about Texas water policy?","correct":"Texas groundwater regulation aquifer policy site:.gov","distractors":["water","Texas stuff","interesting policy"],"explanation":"Specific concepts and source filters improve relevance."},{"prompt":"When should a quotation be used instead of a paraphrase?","correct":"When the original wording is especially precise, authoritative, or important to analyze","distractors":["Whenever the writer wants to avoid understanding the source","For every sentence in a report","To replace all explanation."],"explanation":"Quotation preserves exact language; it should be integrated and interpreted."},{"prompt":"Which note-taking method best supports synthesis?","correct":"Organize evidence from multiple sources by subtopic or claim and record citations.","distractors":["Copy one source from beginning to end.","Mix source wording with personal notes without labels.","Record facts without source information."],"explanation":"Grouping evidence by idea makes comparison and synthesis possible."},{"prompt":"A source’s currency matters most when researching:","correct":"rapidly changing medical guidance.","distractors":["the date of the Declaration of Independence.","the plot of an ancient myth.","a historical spelling in a primary source."],"explanation":"Time-sensitive claims require recent evidence; stable historical facts may rely on older authoritative sources."},{"prompt":"Which domain name alone guarantees that every claim on a page is accurate?","correct":"None of them","distractors":[".org",".com",".edu"],"explanation":"Domain type can provide clues but does not replace evaluation of authorship, evidence, and purpose."},{"prompt":"Which practice is ethical when using an image found online?","correct":"Check licensing and attribution requirements before reproducing it.","distractors":["Assume every image is public domain.","Remove the creator’s name.","Claim the image as original."],"explanation":"Online availability does not eliminate copyright or license conditions."},{"prompt":"Which statement is common knowledge and usually does not require citation?","correct":"The United States has fifty states.","distractors":["A researcher’s new estimate of migration","A distinctive argument from a book","A specific statistic from a report"],"explanation":"Widely known, undisputed facts generally do not require citation, though context matters."},{"prompt":"Which bibliography entry is most useful to readers?","correct":"One that provides enough accurate publication information to locate the source.","distractors":["One listing only the author’s first name","One with no title or date","One based on memory rather than the source."],"explanation":"Citation systems vary, but all aim to identify sources reliably."},{"prompt":"Which visual is most appropriate for comparing quantities across categories?","correct":"Bar graph","distractors":["Unscaled decorative illustration","Timeline with no dates","Map with no geographic variable"],"explanation":"Bar length supports direct comparison among discrete categories."},{"prompt":"Which feature makes an infographic potentially misleading?","correct":"Pictograms change in both height and width, exaggerating differences in area.","distractors":["It cites its data source.","It labels the units.","It uses a consistent scale."],"explanation":"Scaling two dimensions can visually magnify differences beyond the numerical ratio."},{"prompt":"A student finds two credible sources that disagree. What should the student do?","correct":"Compare methods, evidence, dates, definitions, and scope, then represent the disagreement accurately.","distractors":["Choose the source with the more attractive website.","Hide one source.","Assume both claims are identical."],"explanation":"Responsible synthesis investigates why conclusions differ rather than forcing false agreement."}]},"el-assessment":{"label":"Literacy Assessment, Differentiation, and Instruction","description":"Screening, diagnostic assessment, progress monitoring, error analysis, structured literacy, multilingual learners, dyslexia, grouping, and feedback.","group":"Professional Application","questions":[{"prompt":"A student reads accurately but cannot explain the text. Which area should be assessed next most directly?","correct":"Language comprehension, vocabulary, background knowledge, and comprehension strategies","distractors":["Letter naming only","Pencil grip only","Alphabet order only"],"explanation":"Accurate word reading does not guarantee understanding; comprehension components require targeted assessment."},{"prompt":"A student understands text read aloud but cannot decode unfamiliar printed words. This pattern most strongly suggests a need in:","correct":"word recognition and phonics.","distractors":["oral language comprehension only.","background knowledge only.","handwriting only."],"explanation":"Strong listening comprehension with weak independent reading points toward decoding difficulty."},{"prompt":"Which assessment best identifies a student’s phonics patterns of strength and need?","correct":"A decoding inventory using words and pseudowords with controlled spelling patterns","distractors":["A silent reading-interest survey only","A general intelligence score","A handwriting rubric only"],"explanation":"Pattern-controlled word reading reveals which correspondences transfer to unfamiliar words."},{"prompt":"Why are pseudowords useful in decoding assessment?","correct":"They show whether a student can apply phonics rather than relying on memorized words.","distractors":["They measure background knowledge.","They are used to assess handwriting speed only.","They allow context guessing."],"explanation":"Because pseudowords are unfamiliar, successful reading requires grapheme–phoneme application."},{"prompt":"Which is a formative assessment?","correct":"An exit response used to plan the next day’s lesson","distractors":["A final state examination only","A report-card grade after instruction ends","A diploma."],"explanation":"Formative assessments inform ongoing teaching and learning."},{"prompt":"Which is a summative assessment?","correct":"A cumulative end-of-unit assessment","distractors":["Teacher observation during guided practice","A quick check before reteaching","A draft conference."],"explanation":"Summative assessment evaluates learning after a defined period."},{"prompt":"A running record is most useful for examining:","correct":"oral reading accuracy, error patterns, self-corrections, and fluency in connected text.","distractors":["phoneme awareness without print only.","essay organization only.","listening comprehension only."],"explanation":"Running records capture how a student processes connected print."},{"prompt":"Which response to an oral-reading error is most instructionally useful?","correct":"Analyze whether the error reflects graphophonic, morphological, syntactic, or meaning information and target the underlying need.","distractors":["Count every error as identical.","Tell the student to look at the picture for every word.","Ignore repeated error patterns."],"explanation":"Qualitative error analysis helps identify the process causing difficulty."},{"prompt":"Universal screening is intended primarily to:","correct":"identify students who may be at risk and need closer assessment or support.","distractors":["provide a complete diagnosis by itself.","replace classroom instruction.","assign permanent labels."],"explanation":"Screening is brief and broad; it signals who may require further assessment."},{"prompt":"Progress monitoring is used to:","correct":"measure growth frequently and evaluate response to instruction or intervention.","distractors":["determine one-time eligibility only.","replace the intervention.","compare handwriting styles."],"explanation":"Repeated measures show whether learning is improving at an adequate rate."},{"prompt":"Diagnostic assessment is used to:","correct":"investigate specific skills and causes of difficulty in depth.","distractors":["rank students by popularity.","provide only a final grade.","avoid instructional planning."],"explanation":"Diagnostic tools clarify patterns of strengths and needs."},{"prompt":"Which instructional response is most appropriate when many students miss the same skill?","correct":"Reteach explicitly using a different representation, guided practice, and immediate checks for understanding.","distractors":["Assume the class is incapable.","Continue without addressing the gap.","Assign the same independent work with no feedback."],"explanation":"A widespread error suggests instruction should be adjusted and effectiveness checked."},{"prompt":"Which support maintains grade-level comprehension demands for a student with decoding difficulty?","correct":"Provide accessible text support or read-aloud access while separately teaching decoding.","distractors":["Replace the content with much simpler ideas permanently.","Stop all grade-level knowledge building.","Assess only handwriting."],"explanation":"Students can develop language and knowledge while receiving targeted foundational-skills intervention."},{"prompt":"Which practice best supports multilingual learners’ reading development?","correct":"Build on oral language and background knowledge while explicitly teaching English sounds, spelling, vocabulary, and syntax.","distractors":["Treat home-language knowledge as interference only.","Avoid explicit instruction.","Assume conversational fluency equals academic reading proficiency."],"explanation":"Instruction should recognize linguistic assets while teaching language-specific features explicitly."},{"prompt":"A student with dyslexia is most likely to need:","correct":"explicit, systematic, cumulative instruction in phonological awareness, phonics, spelling, and word recognition.","distractors":["more guessing from pictures.","less practice with print.","only silent independent reading."],"explanation":"Dyslexia commonly affects accurate and fluent word reading and spelling and responds to structured literacy instruction."},{"prompt":"Which feedback is most actionable?","correct":"Your evidence is relevant; now explain how it supports the claim in sentence three.","distractors":["Try harder.","This is bad.","Add more."],"explanation":"Actionable feedback identifies a specific strength and next step."},{"prompt":"Which grouping practice is most appropriate?","correct":"Use flexible groups based on current skill data and change them as students progress.","distractors":["Keep fixed ability groups for the entire year.","Group students by behavior only.","Use the same lesson regardless of need."],"explanation":"Flexible grouping responds to changing evidence and avoids permanent labels."},{"prompt":"A decodable text is designed primarily to:","correct":"give students connected-text practice with phonics patterns they have been taught.","distractors":["teach all content knowledge through restricted vocabulary forever.","encourage guessing from illustrations.","replace rich read-alouds and authentic literature."],"explanation":"Decodable text supports early application of taught correspondences and should coexist with rich language experiences."},{"prompt":"Which sequence reflects gradual release of responsibility?","correct":"Teacher modeling → guided practice → collaborative or supported practice → independent application","distractors":["Independent test → no instruction → lecture","Memorization → guessing → grading","Student confusion → harder assignment."],"explanation":"Support is deliberately reduced as competence increases."},{"prompt":"Which statement about assessment accommodations is most accurate?","correct":"They should provide access without changing the construct the assessment is intended to measure.","distractors":["They should make every item easier.","They are identical for every student.","They replace the need for instruction."],"explanation":"Valid accommodations reduce irrelevant barriers while preserving the target skill."}]}},"exams":{"ec6-elar":{"id":"ec6-elar","family":"TExES Core Subjects EC–6","code":"901","title":"Core Subjects EC–6 English Language Arts and Reading","shortTitle":"EC–6 ELAR 901","description":"Elementary ELAR and reading preparation emphasizing grades 4–6 language, word analysis, fluency, comprehension, writing, inquiry, media, and literacy assessment.","fullCount":45,"duration":70,"forms":4,"topicVersions":3,"topicCount":10,"categories":["el-oral","el-phonics","el-fluency","el-vocabulary","el-literary","el-informational","el-writing","el-grammar","el-research","el-assessment"],"weights":{"el-oral":4,"el-phonics":5,"el-fluency":4,"el-vocabulary":4,"el-literary":5,"el-informational":5,"el-writing":5,"el-grammar":5,"el-research":3,"el-assessment":5},"note":"The official ELAR 901 subject exam has 45 selected-response questions. These forms preserve that length and cover the current grades 4–6 literacy competencies."},"core48-elar":{"id":"core48-elar","family":"TExES Core Subjects 4–8","code":"806","title":"Core Subjects 4–8 English Language Arts and Reading","shortTitle":"Core 4–8 ELAR 806","description":"Middle-level generalist ELAR preparation across oral language, reading foundations, comprehension, writing, conventions, inquiry, media, and assessment.","fullCount":74,"duration":115,"forms":4,"topicVersions":3,"topicCount":10,"categories":["el-oral","el-phonics","el-fluency","el-vocabulary","el-literary","el-informational","el-writing","el-grammar","el-research","el-assessment"],"weights":{"el-oral":6,"el-phonics":7,"el-fluency":5,"el-vocabulary":7,"el-literary":9,"el-informational":9,"el-writing":8,"el-grammar":8,"el-research":6,"el-assessment":9},"note":"The official ELAR 806 subject exam has 74 selected-response questions. These forms preserve that length and report results by major literacy component."},"elar48":{"id":"elar48","family":"TExES","code":"217","title":"English Language Arts and Reading 4–8","shortTitle":"ELAR 4–8 (217)","description":"Standalone ELAR preparation for the 90 selected-response questions, with separate guided constructed-response practice below.","fullCount":90,"duration":285,"forms":4,"topicVersions":3,"topicCount":12,"categories":["el-oral","el-phonics","el-fluency","el-vocabulary","el-literary","el-informational","el-writing","el-grammar","el-research","el-assessment"],"weights":{"el-oral":5,"el-phonics":12,"el-fluency":8,"el-vocabulary":11,"el-literary":11,"el-informational":12,"el-writing":8,"el-grammar":6,"el-research":3,"el-assessment":14},"note":"The official ELAR 4–8 (217) exam contains 90 selected-response questions and one constructed response. The objective forms approximate the published domains; writing labs provide separate response practice."},"str293":{"id":"str293","family":"TExES","code":"293","title":"Science of Teaching Reading","shortTitle":"Science of Teaching Reading (293)","description":"Foundational reading development, comprehension, assessment, and evidence-based reading instruction for prekindergarten through grade 6.","fullCount":90,"duration":285,"forms":4,"topicVersions":3,"topicCount":12,"categories":["el-oral","el-phonological","el-phonics","el-fluency","el-vocabulary","el-literary","el-informational","el-assessment"],"weights":{"el-oral":7,"el-phonological":15,"el-phonics":21,"el-fluency":12,"el-vocabulary":11,"el-literary":8,"el-informational":8,"el-assessment":8},"note":"The official STR 293 exam contains 90 selected-response questions and one constructed response. These forms emphasize its foundational-skills and comprehension balance; separate response labs are included."}},"labs":[{"id":"elar-cr-1","exam":"ELAR 4–8 (217)","title":"Reading and Writing Analysis Lab 1","description":"Analyze a student response and plan evidence-based instruction.","scenario":"<h3>Student reading and response</h3><p>A seventh-grade student reads an informational article accurately but writes: “The author thinks parks are good because trees are nice.” The article argues that urban parks reduce heat, manage stormwater, and provide public space. The student copied one sentence about shade but did not explain how it supported the author’s claim.</p><h3>Additional evidence</h3><ul><li>Oral discussion: the student identifies several details when prompted.</li><li>Writing sample: paragraphs often lack topic sentences and evidence explanations.</li><li>Vocabulary: the student is unsure of <em>stormwater</em> and <em>infrastructure</em>.</li></ul>","prompt":"Write a response that identifies the student’s most important literacy need, supports the analysis with evidence from the exhibits, and describes an explicit instructional strategy and a way to monitor progress.","checklist":["State one precise, high-priority need.","Use at least two pieces of exhibit evidence.","Explain the relationship between comprehension, vocabulary, and written evidence use.","Describe explicit modeling and guided practice.","Include a specific formative measure of progress."],"outline":["Name the primary need and briefly distinguish it from skills the student has already demonstrated.","Cite evidence from the written response, oral discussion, and vocabulary information.","Describe modeling a claim–evidence–reasoning response with vocabulary support.","Explain guided practice, feedback, and gradual release.","Specify how later responses will be scored or compared."]},{"id":"elar-cr-2","exam":"ELAR 4–8 (217)","title":"Reading and Writing Analysis Lab 2","description":"Use multiple data sources to design a targeted lesson.","scenario":"<h3>Student profile</h3><p>A fifth-grade student reads grade-level narrative text with strong expression but frequently misreads unfamiliar multisyllabic words in science and social studies. The student recognizes common prefixes but does not consistently identify roots or suffixes. Listening comprehension is strong.</p><h3>Work sample</h3><p>The student reads <em>unpredictable</em> as “un-pretty-table” and <em>transportation</em> as “trans-port-tation.”</p>","prompt":"Analyze the student’s word-reading need and propose instruction that connects morphological and syllabic analysis to accurate reading in content-area text. Include progress monitoring.","checklist":["Identify decoding—not general comprehension—as the priority.","Analyze the specific errors.","Include explicit modeling of morphemes and syllable division.","Apply learning in authentic content text.","Name a repeatable progress measure."],"outline":["State the strength in oral comprehension and fluency.","Explain what the errors reveal about multisyllabic decoding.","Model affix/base analysis and flexible syllable division.","Use guided word lists followed by connected science or social-studies passages.","Monitor accuracy on taught and untaught transfer words."]},{"id":"str-cr-1","exam":"Science of Teaching Reading (293)","title":"Foundational Skills Response Lab 1","description":"Analyze early-reading data and propose systematic instruction.","scenario":"<h3>Kindergarten data</h3><ul><li>Letter names: 49/52</li><li>Letter sounds: 31/40 common correspondences</li><li>Phoneme blending: 3/10</li><li>Phoneme segmentation: 2/10</li><li>Word reading: recognizes several memorized words but guesses unfamiliar CVC words from pictures</li></ul><p>When shown <em>map</em>, the student says “house” after looking at the illustration.</p>","prompt":"Identify the student’s primary foundational-reading needs and describe a systematic instructional plan that integrates phonemic awareness and phonics. Explain how progress will be monitored.","checklist":["Interpret all relevant data rather than naming one low score.","Address phoneme blending and segmentation explicitly.","Connect phonemes to graphemes and blending in print.","Discourage guessing from pictures as a word-identification strategy.","Include cumulative review and a progress measure."],"outline":["State that letter knowledge is a relative strength but phoneme manipulation and decoding are weak.","Describe oral blending and segmentation with gradual use of counters or sound boxes.","Map sounds to letters and teach continuous blending of CVC words.","Practice in controlled word lists and decodable text.","Monitor pseudoword and CVC reading plus phoneme tasks weekly."]},{"id":"str-cr-2","exam":"Science of Teaching Reading (293)","title":"Comprehension Response Lab 2","description":"Plan instruction for a student with strong decoding but weak comprehension.","scenario":"<h3>Grade 3 data</h3><ul><li>Word reading accuracy: 97%</li><li>Oral reading rate: near grade benchmark</li><li>Listening vocabulary: below benchmark</li><li>Literal questions: 4/5</li><li>Inference questions: 1/5</li><li>Summary: lists details but omits the central idea</li></ul><p>The science passage includes the words <em>adaptation</em>, <em>environment</em>, and <em>survive</em>.</p>","prompt":"Analyze the student’s comprehension profile and describe instruction in vocabulary, inferencing, and summarizing that uses the passage evidence. Include a way to measure response to instruction.","checklist":["Recognize decoding and basic fluency as relative strengths.","Identify vocabulary, inferencing, and central-idea synthesis needs.","Use explicit, text-based instruction.","Model how evidence supports an inference.","Specify progress monitoring with comparable passages."],"outline":["Summarize the pattern of strengths and needs.","Preteach and revisit essential vocabulary using morphology and examples.","Model think-alouds linking text evidence and background knowledge.","Teach a central-idea/detail organizer and concise summary frame.","Track vocabulary, inference, and summary rubric scores over time."]}]};const LETTERS=["A","B","C","D"];
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function rng(seed){let a=hash(seed)||1;return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296;};}
function shuffle(r,a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function normalizePrompt(s){return String(s||"").replace(/\s+/g," ").trim().toLowerCase();}
function makePrepared({prompt,stimulus="",choices,answer,explanation},r,catId,idTag){
  const opts=choices.map((text,i)=>({text,ok:i===answer}));
  const mixed=shuffle(r,opts);
  return {id:`${catId}-${hash(idTag).toString(36)}`,prompt,stimulus,choices:mixed.map(x=>x.text),answer:mixed.findIndex(x=>x.ok),explanation,categoryId:catId,categoryLabel:DATA.categories[catId].label};
}
function directVariant(raw,r,catId,baseIndex,variant,seed){
  const d=raw.distractors.slice(0,3);
  const cat=DATA.categories[catId];
  const otherExplanations=[];
  for(let j=1;j<cat.questions.length&&otherExplanations.length<3;j++){
    const e=cat.questions[(baseIndex+j)%cat.questions.length].explanation;
    if(e&&e!==raw.explanation&&!otherExplanations.includes(e))otherExplanations.push(e);
  }
  while(otherExplanations.length<3)otherExplanations.push("This statement describes a different principle and does not justify the answer.");

  if(variant===0){
    return makePrepared({prompt:raw.prompt,stimulus:raw.stimulus||"",choices:[raw.correct,...d],answer:0,explanation:raw.explanation},r,catId,`${seed}:${baseIndex}:v0`);
  }
  // Full-form parallel items: compare the correct response with one plausible distractor.
  if(variant>=1&&variant<=3){
    const k=variant-1;
    const prompt=`${raw.prompt}<div class="comparison-box"><p>A candidate is comparing two possible responses.</p><p><strong>I.</strong> ${raw.correct}<br><strong>II.</strong> ${d[k]}</p><p>Which statement is correct?</p></div>`;
    return makePrepared({prompt,stimulus:raw.stimulus||"",choices:["I only","II only","Both I and II","Neither I nor II"],answer:0,explanation:`Response I is correct and response II is not correct in this context. ${raw.explanation}`},r,catId,`${seed}:${baseIndex}:v${variant}`);
  }
  // Topic Version 1 style: diagnose and correct a common wrong answer.
  if(variant===4){
    const prompt=`<div class="error-analysis"><p>A student selected <strong>${d[0]}</strong> for the question below.</p><div class="mini-stem">${raw.prompt}</div><p>Which response should replace the student's answer?</p></div>`;
    return makePrepared({prompt,stimulus:raw.stimulus||"",choices:[raw.correct,...d],answer:0,explanation:`The student's selected response is not correct. ${raw.explanation}`},r,catId,`${seed}:${baseIndex}:v4`);
  }
  // Topic Version 2 style: focus on the reasoning that supports the answer.
  if(variant===5){
    const prompt=`<div class="reasoning-check"><p>For the question below, suppose a student selects <strong>${raw.correct}</strong>.</p><div class="mini-stem">${raw.prompt}</div><p>Which explanation best justifies that answer?</p></div>`;
    return makePrepared({prompt,stimulus:raw.stimulus||"",choices:[raw.explanation,...otherExplanations],answer:0,explanation:raw.explanation},r,catId,`${seed}:${baseIndex}:v5`);
  }
  // Topic Version 3 style: select the response and supporting reason together.
  if(variant===6){
    const prompt=`<div class="reasoning-check"><p>Which response-and-reason pair correctly answers the question below?</p><div class="mini-stem">${raw.prompt}</div></div>`;
    const choices=[
      `<strong>${raw.correct}</strong> — ${raw.explanation}`,
      `<strong>${d[0]}</strong> — ${otherExplanations[0]}`,
      `<strong>${d[1]}</strong> — ${otherExplanations[1]}`,
      `<strong>${d[2]}</strong> — ${otherExplanations[2]}`
    ];
    return makePrepared({prompt,stimulus:raw.stimulus||"",choices,answer:0,explanation:`The correct response is ${raw.correct}. ${raw.explanation}`},r,catId,`${seed}:${baseIndex}:v6`);
  }
  // Random-practice extra style.
  const prompt=`<div class="error-analysis"><p>A student selected <strong>${d[2]}</strong> for the question below.</p><div class="mini-stem">${raw.prompt}</div><p>Which response should replace the student's answer?</p></div>`;
  return makePrepared({prompt,stimulus:raw.stimulus||"",choices:[raw.correct,...d],answer:0,explanation:`The student's selected response is not correct. ${raw.explanation}`},r,catId,`${seed}:${baseIndex}:v7`);
}
function permutationFor(catId,examId,kind,index){
  const n=DATA.categories[catId].questions.length;
  return shuffle(rng(`${examId}:${catId}:${kind}:${index}:base-order:v3`),Array.from({length:n},(_,i)=>i));
}
function fixedCategoryQuestions(examId,catId,count,kind,index){
  const cat=DATA.categories[catId];
  // Use every direct base item before recycling the same concept in a
  // different reasoning format. Because each assessment asks no more
  // questions from a category than the category contains base items, a
  // single form/version never repeats the same source question.
  const baseOrder=permutationFor(catId,examId,kind,0);
  const r=rng(`${examId}:${catId}:${kind}:${index}:choices:v4`);
  const out=[];
  for(let i=0;i<count;i++){
    const position=index*count+i;
    const baseIndex=baseOrder[position%baseOrder.length];
    const occurrence=Math.floor(position/baseOrder.length);
    const variant=kind==="full"?Math.min(occurrence,3):4+Math.min(occurrence,3);
    const q=directVariant(cat.questions[baseIndex],r,catId,baseIndex,variant,`${examId}:${kind}:${index}:${i}:v4`);
    out.push(q);
  }
  return out;
}
function randomCategoryQuestions(examId,catId,count,seed){
  const cat=DATA.categories[catId],r=rng(`${seed}:virtual:v3`),used=new Set(),out=[];
  let guard=0;
  while(out.length<count&&guard++<10000){
    const baseIndex=Math.floor(r()*cat.questions.length);
    const variant=Math.floor(r()*8);
    const key=`${baseIndex}:${variant}`;
    if(used.has(key))continue;
    used.add(key);
    out.push(directVariant(cat.questions[baseIndex],r,catId,baseIndex,variant,`${seed}:${out.length}`));
  }
  if(out.length<count)throw new Error(`Unable to create ${count} distinct questions for ${catId}`);
  return out;
}
function parseFixedForm(seed){const m=String(seed).match(/form-([A-Z])/);return m?m[1].charCodeAt(0)-65:null;}
function parseFixedTopic(seed){const m=String(seed).match(/topic-(\d+)/);return m?Number(m[1])-1:null;}
function full(id,seed){
  const e=DATA.exams[id],formIndex=parseFixedForm(seed),r=rng(`${seed}:shuffle:v3`);let qs=[];
  e.categories.forEach(c=>{const count=e.weights[c];qs.push(...(formIndex!==null?fixedCategoryQuestions(id,c,count,"full",formIndex):randomCategoryQuestions(id,c,count,`${seed}:${c}`)));});
  return shuffle(r,qs).map((q,i)=>({...q,order:i+1}));
}
function topic(examId,catId,seed){
  const e=DATA.exams[examId];if(!e.categories.includes(catId))throw Error("Topic not in exam");
  const topicIndex=parseFixedTopic(seed);
  const qs=topicIndex!==null?fixedCategoryQuestions(examId,catId,e.topicCount,"topic",topicIndex):randomCategoryQuestions(examId,catId,e.topicCount,seed);
  return qs.map((q,i)=>({...q,order:i+1}));
}
global.PracticeData={...DATA,LETTERS,generateFullExam:full,generateTopicQuiz:topic};
})(window);